import { z } from 'zod';

export const SensorReadingSchema = z.object({
  deviceId:           z.string().min(3).max(50),
  ts:                 z.number().positive(),
  temperature_c:      z.number().min(-40).max(80),
  humidity_pct:       z.number().min(0).max(100),
  vibration_magnitude:z.number().min(0).max(20),
  accel_x:            z.number(),
  accel_y:            z.number(),
  accel_z:            z.number(),
  firmware_version:   z.string().optional(),
});

export const SensorThresholdSchema = z.object({
  temp_min_c:        z.number().min(-40).max(80),
  temp_max_c:        z.number().min(-40).max(80),
  humidity_max_pct:  z.number().min(0).max(100),
  vibration_max_g:   z.number().min(0).max(20),
}).refine(d => d.temp_min_c < d.temp_max_c, {
  message: 'temp_min_c must be less than temp_max_c',
});

export const DeviceRegisterSchema = z.object({
  deviceId:    z.string().regex(/^[a-z0-9-]{3,50}$/, { message: 'deviceId must be lowercase letters, numbers, hyphens only' }),
  truckLabel:  z.string().min(2).max(100),
  driverId:    z.string().uuid().optional(),
  alertConfig: SensorThresholdSchema.optional(),
});

export type SensorReading    = z.infer<typeof SensorReadingSchema>;
export type SensorThreshold  = z.infer<typeof SensorThresholdSchema>;
export type DeviceRegister   = z.infer<typeof DeviceRegisterSchema>;

export const DEFAULT_ALERT_CONFIG: SensorThreshold = {
  temp_min_c:       2,
  temp_max_c:       8,
  humidity_max_pct: 85,
  vibration_max_g:  0.5,
};

import { db } from '@/db';
import { iotDevices } from '@/db/schema';
import { DEFAULT_ALERT_CONFIG, SensorThreshold } from '@/schemas/sensor.schema';

export type AlertType = 'temp_high' | 'temp_low' | 'humidity_high' | 'vibration_high';

export interface ThresholdBreach {
  type:      AlertType;
  value:     number;
  threshold: number;
}

export interface AlertConfig extends SensorThreshold {}

/**
 * Load all device alert configs into a Map.
 * Called on worker startup and refreshed every 5 minutes.
 */
export async function loadDeviceConfigs(): Promise<Map<string, AlertConfig>> {
  const devices = await db.select({
    deviceId:    iotDevices.deviceId,
    alertConfig: iotDevices.alertConfig,
  }).from(iotDevices);

  const map = new Map<string, AlertConfig>();
  for (const device of devices) {
    const config = (device.alertConfig as AlertConfig) ?? DEFAULT_ALERT_CONFIG;
    map.set(device.deviceId, config);
  }
  return map;
}

/**
 * Evaluate a sensor reading against thresholds.
 * Returns an array of breaches (can be multiple per reading).
 * Empty array = no breach.
 */
export function evaluateThresholds(
  reading: { temperature_c: number; humidity_pct: number; vibration_magnitude: number },
  config:  AlertConfig
): ThresholdBreach[] {
  const breaches: ThresholdBreach[] = [];

  if (reading.temperature_c > config.temp_max_c) {
    breaches.push({ type: 'temp_high', value: reading.temperature_c, threshold: config.temp_max_c });
  }
  if (reading.temperature_c < config.temp_min_c) {
    breaches.push({ type: 'temp_low', value: reading.temperature_c, threshold: config.temp_min_c });
  }
  if (reading.humidity_pct > config.humidity_max_pct) {
    breaches.push({ type: 'humidity_high', value: reading.humidity_pct, threshold: config.humidity_max_pct });
  }
  if (reading.vibration_magnitude > config.vibration_max_g) {
    breaches.push({ type: 'vibration_high', value: reading.vibration_magnitude, threshold: config.vibration_max_g });
  }

  return breaches;
}

