#pragma once

// ─────────────────────────────────────────────────────────────────────────────
//  TruckNet ESP32 — Credentials Template
//
//  1. Copy this file:  cp credentials.example.h credentials.h
//  2. Fill in your real values in credentials.h
//  3. credentials.h is in .gitignore — it will never be committed
// ─────────────────────────────────────────────────────────────────────────────

// WiFi network the truck connects to (hotspot or depot WiFi)
#define WIFI_SSID         "YOUR_WIFI_SSID"
#define WIFI_PASSWORD     "YOUR_WIFI_PASSWORD"

// MQTT broker credentials — must match Mosquitto passwd file
// Get MQTT_PASSWORD from your server .env file
#define MQTT_USERNAME     "trucknet"
#define MQTT_PASSWORD     "YOUR_MQTT_PASSWORD"

// OTA password — used to push firmware updates over WiFi after first flash
#define OTA_PASSWORD      "YOUR_OTA_PASSWORD"

#pragma once

// credentials.h is gitignored — copy from credentials.example.h
#include "../config/credentials.h"

// ─────────────────────────────────────────────────────────────────────────────
//  TruckNet ESP32 — Central Configuration
//  CHANGE DEVICE_ID and MQTT_BROKER_HOST before flashing each unit.
// ─────────────────────────────────────────────────────────────────────────────

// ── DEVICE (change per unit) ──────────────────────────────────────────────────
// Must match a row registered in iot_devices table via POST /api/admin/sensors/{deviceId}/register
// Format: lowercase, numbers, hyphens only. Examples: truck-001, truck-042
#define DEVICE_ID           "truck-001"
#define FIRMWARE_VERSION    "1.0.0"

// ── BROKER (change to your server IP or domain) ───────────────────────────────
// Docker internal: use service name 'mosquitto' inside compose network
// External access: your server's public IP or domain, e.g. "mqtt.mydomain.com"
#define MQTT_BROKER_HOST        "192.168.1.100"
#define MQTT_BROKER_PORT        1883
#define MQTT_QOS                1
#define MQTT_KEEPALIVE_SECONDS  60
#define MQTT_RECONNECT_DELAY_MS 3000
#define MQTT_MAX_PACKET_SIZE    512  // default 256 is too small for our payload

// ── WIFI ─────────────────────────────────────────────────────────────────────
#define WIFI_RECONNECT_INTERVAL_MS  5000
#define WIFI_MAX_RETRIES            20

// ── PINS ─────────────────────────────────────────────────────────────────────
#define DHT_PIN             4      // DHT22 data → GPIO4 (with 10kΩ pull-up to 3.3V)
#define DHT_TYPE            DHT22
#define MPU_SDA_PIN         21     // MPU6050 SDA → GPIO21
#define MPU_SCL_PIN         22     // MPU6050 SCL → GPIO22
#define LED_PIN             2      // onboard LED — most ESP32 DevKit V1 boards
#define LED_BLINK_ON_PUBLISH true  // blink on every successful MQTT publish

// ── TIMING ───────────────────────────────────────────────────────────────────
#define READ_INTERVAL_MS            5000   // sensor read + MQTT publish interval
#define STATUS_PUBLISH_INTERVAL_MS  30000  // heartbeat 'online' status
#define WATCHDOG_TIMEOUT_SECONDS    30     // hardware reset if loop stalls

// ── LOCAL THRESHOLDS (onboard LED warning only) ───────────────────────────────
// Server-side thresholds in iot_devices.alert_config are authoritative for admin alerts.
#define TEMP_WARN_MAX_C        8.0f
#define TEMP_WARN_MIN_C        2.0f
#define HUMIDITY_WARN_MAX_PCT  85.0f
#define VIBRATION_WARN_MAX_G   0.5f

#pragma once

// ─────────────────────────────────────────────────────────────────────────────
//  TruckNet ESP32 — Sensor Interface
//  DHT22  → temperature + humidity (GPIO4)
//  MPU6050 → 3-axis accelerometer, vibration magnitude (I2C)
// ─────────────────────────────────────────────────────────────────────────────

struct DHT22Reading {
  float temperature_c;
  float humidity_pct;
  bool  valid;
};

struct MPU6050Reading {
  float accel_x;  // G-force
  float accel_y;
  float accel_z;
  float gyro_x;   // rad/s
  float gyro_y;
  float gyro_z;
  bool  valid;
};

struct SensorBundle {
  DHT22Reading   dht;
  MPU6050Reading mpu;
  float          vibration_magnitude;  // sqrt(ax²+ay²+az²) in G
  unsigned long  timestamp_ms;         // millis() at read time
};

bool         initSensors();   // returns false if MPU6050 not found on I2C
DHT22Reading readDHT22();     // up to 3 retries, 2s apart
MPU6050Reading readMPU6050(); // returns { valid: false } on I2C error
float        computeVibrationMagnitude(float ax, float ay, float az);
SensorBundle readAll();       // combines both sensors into one bundle

#include "sensors.h"
#include "config.h"
#include <DHT.h>
#include <Adafruit_MPU6050.h>
#include <Adafruit_Sensor.h>
#include <Wire.h>
#include <math.h>

static DHT             dht(DHT_PIN, DHT_TYPE);
static Adafruit_MPU6050 mpu;
static bool            mpuReady = false;

bool initSensors() {
  Serial.println("[Sensors] Initializing...");
  dht.begin();
  Serial.println("[Sensors] DHT22 ready on GPIO" + String(DHT_PIN));

  Wire.begin(MPU_SDA_PIN, MPU_SCL_PIN);
  if (!mpu.begin()) {
    Serial.println("[Sensors][ERROR] MPU6050 not found — check wiring: SDA→GPIO21, SCL→GPIO22, VCC→3.3V, AD0→GND");
    mpuReady = false;
    return false;
  }

  mpu.setAccelerometerRange(MPU6050_RANGE_8_G);
  mpu.setGyroRange(MPU6050_RANGE_500_DEG);
  mpu.setFilterBandwidth(MPU6050_BAND_21_HZ);

  // Warm-up: discard first 10 readings
  Serial.print("[Sensors] MPU6050 warm-up");
  for (int i = 0; i < 10; i++) {
    sensors_event_t a, g, t; mpu.getEvent(&a, &g, &t); delay(50); Serial.print(".");
  }
  Serial.println(" done");

  mpuReady = true;
  return true;
}

DHT22Reading readDHT22() {
  for (int i = 0; i < 3; i++) {
    float t = dht.readTemperature();
    float h = dht.readHumidity();
    if (!isnan(t) && !isnan(h)) return { t, h, true };
    if (i < 2) { Serial.println("[Sensors][WARN] DHT22 retry " + String(i+1) + "/3"); delay(2000); }
  }
  Serial.println("[Sensors][ERROR] DHT22 failed after 3 attempts");
  return { 0, 0, false };
}

MPU6050Reading readMPU6050() {
  if (!mpuReady) return { 0,0,0,0,0,0, false };
  sensors_event_t a, g, t;
  mpu.getEvent(&a, &g, &t);
  return {
    a.acceleration.x / 9.81f,
    a.acceleration.y / 9.81f,
    a.acceleration.z / 9.81f,
    g.gyro.x, g.gyro.y, g.gyro.z,
    true
  };
}

float computeVibrationMagnitude(float ax, float ay, float az) {
  return sqrt(ax*ax + ay*ay + az*az);
}

SensorBundle readAll() {
  SensorBundle b;
  b.timestamp_ms        = millis();
  b.dht                 = readDHT22();
  b.mpu                 = readMPU6050();
  b.vibration_magnitude = b.mpu.valid ? computeVibrationMagnitude(b.mpu.accel_x, b.mpu.accel_y, b.mpu.accel_z) : 0.0f;
  return b;
}

#include "payload.h"
#include "config.h"
#include <ArduinoJson.h>
#include <time.h>

static bool          ntpSynced  = false;
static time_t        bootEpoch  = 0;
static unsigned long bootMs     = 0;

void syncNTP() {
  Serial.print("[NTP] Syncing");
  configTime(0, 0, "pool.ntp.org", "time.google.com");
  struct tm ti;
  int retries = 0;
  while (!getLocalTime(&ti) && retries < 20) { delay(500); Serial.print("."); retries++; }
  if (retries < 20) {
    bootEpoch = time(nullptr); bootMs = millis(); ntpSynced = true;
    Serial.println(" OK: " + String((long)bootEpoch));
  } else {
    Serial.println(" FAILED — using millis() fallback");
  }
}

unsigned long long getCurrentEpochMs() {
  if (ntpSynced) return ((unsigned long long)bootEpoch * 1000ULL) + (millis() - bootMs);
  return (unsigned long long)millis();
}

String buildReadingPayload(const SensorBundle& b) {
  StaticJsonDocument<512> doc;
  doc["deviceId"]             = DEVICE_ID;
  doc["ts"]                   = getCurrentEpochMs();
  doc["temperature_c"]        = round(b.dht.temperature_c * 10.0f) / 10.0f;
  doc["humidity_pct"]         = round(b.dht.humidity_pct  * 10.0f) / 10.0f;
  doc["vibration_magnitude"]  = round(b.vibration_magnitude * 1000.0f) / 1000.0f;
  doc["accel_x"]              = round(b.mpu.accel_x * 1000.0f) / 1000.0f;
  doc["accel_y"]              = round(b.mpu.accel_y * 1000.0f) / 1000.0f;
  doc["accel_z"]              = round(b.mpu.accel_z * 1000.0f) / 1000.0f;
  doc["firmware_version"]     = FIRMWARE_VERSION;
  String out; serializeJson(doc, out); return out;
}

String buildStatusPayload(const char* status) {
  StaticJsonDocument<128> doc;
  doc["deviceId"] = DEVICE_ID; doc["status"] = status; doc["ts"] = getCurrentEpochMs();
  String out; serializeJson(doc, out); return out;
}

String buildLwtPayload() { return buildStatusPayload("offline"); }

#pragma once
#include <WiFi.h>
#include <PubSubClient.h>

extern unsigned long currentReadIntervalMs;  // modified by set_interval command

void initMqtt(WiFiClient& wc);   // sets up PubSubClient — does NOT connect
bool ensureConnected();          // reconnect with backoff — publishes online + subscribes on connect
bool publishReading(const String& payload);
bool publishStatus(const String& payload, bool retained);
void mqttLoop();                 // must be called every loop iteration
bool mqttConnected();

#include "mqtt_client.h"
#include "config.h"
#include "payload.h"
#include <ArduinoJson.h>

static WiFiClient*   _wc              = nullptr;
static PubSubClient* _client          = nullptr;
static unsigned long _lastReconnectAt = 0;
static unsigned long _backoff         = MQTT_RECONNECT_DELAY_MS;

static char _topicReadings[80];
static char _topicStatus[80];
static char _topicCommand[80];

unsigned long currentReadIntervalMs = READ_INTERVAL_MS;

static void onMessage(char* topic, byte* payload, unsigned int len) {
  String msg; for (unsigned int i = 0; i < len; i++) msg += (char)payload[i];
  Serial.println("[MQTT] Command: " + msg);
  StaticJsonDocument<128> doc;
  if (deserializeJson(doc, msg)) return;
  const char* cmd = doc["cmd"];
  if (cmd && strcmp(cmd, "set_interval") == 0) {
    int s = constrain((int)doc["intervalSeconds"], 1, 60);
    currentReadIntervalMs = (unsigned long)s * 1000UL;
    Serial.println("[MQTT] Interval → " + String(s) + "s");
  }
}

static bool connectMqtt() {
  String cid = String("esp32-") + DEVICE_ID;
  String lwt = buildLwtPayload();
  Serial.print("[MQTT] Connecting as " + cid + "...");
  bool ok = _client->connect(cid.c_str(), MQTT_USERNAME, MQTT_PASSWORD,
                              _topicStatus, MQTT_QOS, true, lwt.c_str());
  if (!ok) { Serial.println(" failed rc=" + String(_client->state())); return false; }
  Serial.println(" OK");
  String online = buildStatusPayload("online");
  _client->publish(_topicStatus, online.c_str(), true);
  _client->subscribe(_topicCommand, MQTT_QOS);
  _backoff = MQTT_RECONNECT_DELAY_MS;
  return true;
}

void initMqtt(WiFiClient& wc) {
  _wc     = &wc;
  _client = new PubSubClient(wc);
  snprintf(_topicReadings, sizeof(_topicReadings), "trucknet/sensors/%s/readings", DEVICE_ID);
  snprintf(_topicStatus,   sizeof(_topicStatus),   "trucknet/sensors/%s/status",   DEVICE_ID);
  snprintf(_topicCommand,  sizeof(_topicCommand),  "trucknet/sensors/%s/command",  DEVICE_ID);
  _client->setServer(MQTT_BROKER_HOST, MQTT_BROKER_PORT);
  _client->setCallback(onMessage);
  _client->setKeepAlive(MQTT_KEEPALIVE_SECONDS);
  _client->setBufferSize(MQTT_MAX_PACKET_SIZE);  // CRITICAL — default 256 truncates payload
}

bool ensureConnected() {
  if (_client->connected()) return true;
  unsigned long now = millis();
  if (now - _lastReconnectAt < _backoff) return false;
  _lastReconnectAt = now;
  bool ok = connectMqtt();
  if (!ok) _backoff = min(_backoff * 2, 30000UL);
  return ok;
}

bool publishReading(const String& p) {
  return _client->publish(_topicReadings, p.c_str(), false);
}
bool publishStatus(const String& p, bool retained) {
  return _client->publish(_topicStatus, p.c_str(), retained);
}
void mqttLoop()     { if (_client) _client->loop(); }
bool mqttConnected(){ return _client && _client->connected(); }

#include "watchdog.h"
#include <esp_task_wdt.h>

void initWatchdog(uint32_t s) {
  esp_task_wdt_init(s, true);   // true = panic (reboot) on timeout
  esp_task_wdt_add(NULL);       // watch main task
  Serial.println("[WDT] Watchdog armed — " + String(s) + "s timeout");
}
void feedWatchdog()    { esp_task_wdt_reset(); }
void disableWatchdog() { esp_task_wdt_delete(NULL); }

#include "ota.h"
#include "watchdog.h"
#include <ArduinoOTA.h>

void initOTA(const char* hostname) {
  ArduinoOTA.setHostname(hostname);
  ArduinoOTA.setPassword(OTA_PASSWORD);
  ArduinoOTA.onStart([]() {
    disableWatchdog();  // prevent reset during flash
    Serial.println("[OTA] Starting update...");
  });
  ArduinoOTA.onEnd([]()   { Serial.println("\n[OTA] Done — rebooting"); });
  ArduinoOTA.onProgress([](unsigned int p, unsigned int t) {
    Serial.printf("[OTA] %u%%\r", (p * 100) / t);
  });
  ArduinoOTA.onError([](ota_error_t e) {
    Serial.println("[OTA][ERROR] " + String(e));
  });
  ArduinoOTA.begin();
  Serial.println("[OTA] Ready — hostname: " + String(hostname) + ".local");
}

// ─────────────────────────────────────────────────────────────────────────────
//  TruckNet ESP32 Firmware — main.ino
//  Reads DHT22 + MPU6050 every READ_INTERVAL_MS
//  Publishes JSON to MQTT broker (Mosquitto)
//  Connects to: trucknet/sensors/{DEVICE_ID}/readings
// ─────────────────────────────────────────────────────────────────────────────

#include "config.h"
#include "sensors.h"
#include "payload.h"
#include "mqtt_client.h"
#include "ota.h"
#include "watchdog.h"
#include <WiFi.h>

static WiFiClient    wifiClient;
static unsigned long lastReadTime   = 0;
static unsigned long lastStatusTime = 0;
static bool          sensorsOk      = false;

// ── WiFi ─────────────────────────────────────────────────────────────────────
void connectWiFi() {
  Serial.print("[WiFi] Connecting to " + String(WIFI_SSID));
  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
  int retries = 0;
  while (WiFi.status() != WL_CONNECTED && retries < WIFI_MAX_RETRIES) {
    delay(WIFI_RECONNECT_INTERVAL_MS); Serial.print("."); retries++;
  }
  if (WiFi.status() != WL_CONNECTED) {
    Serial.println("\n[WiFi][ERROR] Failed — restarting in 5s");
    delay(5000); ESP.restart();
  }
  Serial.println("\n[WiFi] Connected: " + WiFi.localIP().toString());
}

// ── Setup ────────────────────────────────────────────────────────────────────
void setup() {
  Serial.begin(115200);
  delay(200);
  Serial.println();
  Serial.println("┌──────────────────────────────────────┐");
  Serial.println("│  TruckNet ESP32  v" + String(FIRMWARE_VERSION) + "              │");
  Serial.println("│  Device: " + String(DEVICE_ID) + "                    │");
  Serial.println("└──────────────────────────────────────┘");

  initWatchdog(WATCHDOG_TIMEOUT_SECONDS);
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(LED_PIN, HIGH);  // LED on during boot

  connectWiFi();
  syncNTP();
  initOTA(DEVICE_ID);

  sensorsOk = initSensors();
  if (!sensorsOk) Serial.println("[WARN] Sensor init failed — will retry in loop");

  initMqtt(wifiClient);
  ensureConnected();

  digitalWrite(LED_PIN, LOW);  // LED off = ready
  Serial.println("[TruckNet] Operational. Publishing every " + String(READ_INTERVAL_MS / 1000) + "s");
}

// ── Loop ─────────────────────────────────────────────────────────────────────
void loop() {
  feedWatchdog();
  handleOTA();

  // WiFi guard
  if (WiFi.status() != WL_CONNECTED) {
    Serial.println("[WiFi] Lost connection — reconnecting");
    connectWiFi();
    return;
  }

  // MQTT guard
  if (!ensureConnected()) { delay(500); return; }
  mqttLoop();

  unsigned long now = millis();

  // ── Sensor read + publish ─────────────────────────────────────────────────
  if (now - lastReadTime >= currentReadIntervalMs) {
    lastReadTime = now;

    if (!sensorsOk) { sensorsOk = initSensors(); }

    SensorBundle bundle = readAll();

    if (bundle.dht.valid && bundle.mpu.valid) {
      String payload = buildReadingPayload(bundle);
      bool   ok      = publishReading(payload);

      if (ok) {
        if (LED_BLINK_ON_PUBLISH) { digitalWrite(LED_PIN, HIGH); delay(30); digitalWrite(LED_PIN, LOW); }
        Serial.println("[READ] T:" + String(bundle.dht.temperature_c, 1) +
                       "C  H:" + String(bundle.dht.humidity_pct, 1) +
                       "%  V:" + String(bundle.vibration_magnitude, 3) + "G");
      } else {
        Serial.println("[READ][WARN] Publish failed");
      }
    } else {
      Serial.println("[READ][WARN] Sensor read failed — skipping");
    }
  }

  // ── Heartbeat status publish ──────────────────────────────────────────────
  if (now - lastStatusTime >= STATUS_PUBLISH_INTERVAL_MS) {
    lastStatusTime = now;
    publishStatus(buildStatusPayload("online"), true);
  }
}
